import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const GENETICS_DISCLOSURE = {
  status: 'conceptual_diagram_only' as const,
  summary:
    'Delivered with Central Dogma pathway schematics, worked Punnett/pedigree inheritance exercises, Hardy–Weinberg population problems, karyotype logic, and pharmacogenetic mechanisms.',
};

function makeGeneticsChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  readingKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  workedCase: { title: string; scenario: string; questions: string[]; solution: string },
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'molecular_genetics',
    chapterCode: `G${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['secondary_premed', 'medical_foundations', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_ncp_bio_9_12', gradeOrYear: 'Grade XII', unitOrModule: `Chromosomes, DNA & Inheritance (${chapterTitle})`, status: 'elective' },
      { frameworkId: 'us_ap_bio', gradeOrYear: 'AP Bio Units 5–6', unitOrModule: `Heredity & Gene Expression (${chapterTitle})`, status: 'optional' },
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–2', unitOrModule: `Medical Genetics & Molecular Biology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Genomics & Molecular Regulation (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Purine/pyrimidine chemistry (F6)', 'Mitosis and meiosis segregation (B7)'],
    learningObjectives: [
      `Explain the molecular machinery and directionality governing ${chapterTitle.toLowerCase()}.`,
      `Apply inheritance rules, probability ratios, or sequence interpretation cleanly to ${chapterTitle.toLowerCase()} scenarios.`,
      `Correlate human genetic defects, chromosomal lesions, or pharmacogenomic polymorphisms with clinical phenotypes.`,
    ],
    depthExplanations: {
      secondary_premed: `${summary} Genes encode functional RNAs and polypeptides passed across generations according to chromosomal segregation and molecular base pairing.`,
      medical_foundations: `${mechanisms.join(' ')} Clinical genetics: ${clinical}`,
      graduate_research: `Chromatin topology (TADs/enhancers), polymerase proofreading kinetics, epigenetic methylation/histone codes, and genome-wide association/pharmacogenomic variant interpretation refine precision reasoning across ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: 'Molecular / Genetic Principle', definition: summary },
      { term: 'Mechanistic Rule', definition: mechanisms[0] ?? summary },
      { term: 'Clinical Genetic Application', definition: clinical },
    ],
    keyFacts: [
      mechanisms[0] ?? summary,
      'Worked genetic probability and pedigree calculation exercises require checking carrier frequency, penetrance, and biological parentage assumptions.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Dominant alleles are always more common and healthier than recessive alleles.', correction: 'Allele frequency depends on evolutionary history and drift (e.g., polydactyly and Huntington alleles are rare despite dominant inheritance).' },
      { misconception: 'One gene always produces strictly one protein.', correction: 'Alternative pre-mRNA splicing, alternative promoters, and post-translational cleavage allow ~20,000 human protein-coding genes to generate >100,000 isoforms.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} connects nucleic-acid base-pairing fidelity, inheritance transmission laws, and modern genomic medicine.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      mechanisms[1] ?? clinical,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'biochemistry', relation: 'Deoxyribonucleotide synthesis and one-carbon methyl donors underpin DNA stability and epigenetics.' },
      { domainId: 'pharmacology', relation: 'Pharmacogenetic enzyme polymorphisms reshape drug clearance and adverse toxicity.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: [],
    visualFormats: ['2d_diagram', 'structured_text'],
    diagram: {
      id: `diag-g${num}`,
      title: `${chapterTitle} — Information & Inheritance Flow`,
      kind: 'pathway',
      caption: summary,
      disclaimer: 'Conceptual molecular/genetic schematic.',
      nodes: [
        { id: 'n1', label: 'Genomic Input / Template', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'blue' },
        { id: 'n2', label: 'Catalytic / Segregation Step', sublabel: mechanisms[1]?.slice(0, 62) || clinical.slice(0, 62), tone: 'teal' },
        { id: 'n3', label: 'Phenotypic / Clinical Outcome', sublabel: clinical.slice(0, 62), tone: 'amber' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Enzyme specificity / Meiotic assortment' },
        { from: 'n2', to: 'n3', label: 'Expression & variant penetrance' },
      ],
    },
    assetDisclosure: GENETICS_DISCLOSURE,
    activity: {
      title: `Worked Genetic Reasoning Exercise (${chapterTitle})`,
      kind: 'calculation',
      prompt: `${workedCase.scenario} Solve: ${workedCase.questions.join(' ')}`,
      keyTakeaway: workedCase.solution,
    },
    readingKeys: [readingKey, 'ncbi_mboc_alberts'],
    shortAnswers: [
      { id: `sa-g${num}-1`, prompt: `Outline the core step-by-step molecular or genetic rules in ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: mechanisms.join(' '), level: 'medical_foundations' },
      { id: `sa-g${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB}.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'secondary_premed' },
      { id: `sa-g${num}-3`, prompt: `Connect ${chapterTitle} to a specific human genetic condition or clinical assay.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'medical_foundations' },
    ],
    appliedCase: {
      id: `app-g${num}-1`,
      title: workedCase.title,
      scenario: workedCase.scenario,
      questions: workedCase.questions,
      workedSolution: workedCase.solution,
      level: 'medical_foundations',
    },
    selfChecks: mcqs,
  };
}

